window.populatePricingPackageSelect = function (selectEl) {
  if (!selectEl || !window.JIMMY_PRICING_DATA) return;
  const data = window.JIMMY_PRICING_DATA;
  const prevValue = selectEl.value;
  selectEl.innerHTML = "";
  const placeholder = document.createElement("option");
  placeholder.value = "";
  placeholder.disabled = true;
  placeholder.selected = true;
  placeholder.className = "bg-gray-900";
  placeholder.textContent = "Select a package";
  selectEl.appendChild(placeholder);
  const pkgGroup = document.createElement("optgroup");
  pkgGroup.label = "The Packages (01–08)";
  pkgGroup.className = "bg-gray-800 text-gray-400";
  data.packages.forEach((pkg) => {
    const opt = document.createElement("option");
    opt.value = pkg.bookingValue;
    opt.className = "bg-gray-900 text-white";
    opt.textContent = pkg.bookingValue;
    pkgGroup.appendChild(opt);
  });
  selectEl.appendChild(pkgGroup);
  const extraGroup = document.createElement("optgroup");
  extraGroup.label = "Optional Extras";
  extraGroup.className = "bg-gray-800 text-gray-400";
  data.extras.forEach((extra) => {
    const opt = document.createElement("option");
    opt.value = extra.bookingValue;
    opt.className = "bg-gray-900 text-white";
    opt.textContent = extra.bookingValue;
    extraGroup.appendChild(opt);
  });
  selectEl.appendChild(extraGroup);
  const soloGroup = document.createElement("optgroup");
  soloGroup.label = "Solo Services";
  soloGroup.className = "bg-gray-800 text-gray-400";
  data.soloGroups.forEach((grp) => {
    grp.items.forEach((item) => {
      const opt = document.createElement("option");
      opt.value = item.bookingValue;
      opt.className = "bg-gray-900 text-white";
      opt.textContent = item.bookingValue;
      soloGroup.appendChild(opt);
    });
  });
  selectEl.appendChild(soloGroup);
  const customOpt = document.createElement("option");
  customOpt.value = "Custom Plan";
  customOpt.className = "bg-gray-900 text-white font-bold";
  customOpt.textContent = "Custom Plan";
  selectEl.appendChild(customOpt);
  const decideOpt = document.createElement("option");
  decideOpt.value = "YOUR CALL";
  decideOpt.className = "bg-gray-900 text-white font-bold";
  decideOpt.textContent = "YOUR CALL";
  selectEl.appendChild(decideOpt);
  if (prevValue) {
    for (let i = 0; i < selectEl.options.length; i++) {
      if (selectEl.options[i].value.toLowerCase() === prevValue.toLowerCase()) {
        selectEl.selectedIndex = i;
        break;
      }
    }
  }
};

window.bookPricingPackage = function (bookingValue) {
  window._bookingFromPricing = true;
  window._bookingPricingPackage = bookingValue || "Custom Plan";
  const selectEl = document.getElementById("req-package");
  if (selectEl && typeof window.populatePricingPackageSelect === "function") {
    window.populatePricingPackageSelect(selectEl);
  }
  if (typeof window.openIWantThisModal === "function") {
    window.openIWantThisModal(bookingValue === "Custom Plan" ? null : bookingValue);
    if (bookingValue === "Custom Plan" && selectEl) {
      selectEl.value = "Custom Plan";
      selectEl.disabled = false;
      selectEl.classList.remove("opacity-50", "pointer-events-none");
    }
  } else {
    const msg = `Hello Jimmy Render,\n\nI'm interested in booking: ${bookingValue || "Custom Plan"}.`;
    window.open(`https://wa.me/201004113127?text=${encodeURIComponent(msg)}`, "_blank");
  }
};

function escapePricingHtml(str) {
  return String(str || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

